from abc import ABC, abstractmethod
from dataclasses import dataclass

class Notifier(ABC):
    @abstractmethod
    def send(self, to: str, msg: str) -> None: ...

class EmailNotifier(Notifier):
    def send(self, to, msg):
        print(f"email to {to}: {msg}")

class SmsNotifier(Notifier):
    def send(self, to, msg):
        print(f"sms to {to}: {msg[:160]}")

@dataclass
class SignupService:
    notifier: Notifier          # composition

    def register(self, contact: str):
        self.notifier.send(contact, "Welcome!")

SignupService(EmailNotifier()).register("a@x.io")
